from typing import List

def is_tree(edges: List[List[int]]) -> bool:
    if not edges: return False
    n = max(max(edges)) + 1
    indegree = [0] * n
    for edge in edges:
        indegree[edge[1]] += 1
    if max(indegree) > 1: return False
    visited = [False] * n
    def dfs(node):
        if visited[node]: return True
        visited[node] = True
        for edge in edges:
            if edge[0] == node:
                if dfs(edge[1]): return True
        return False
    if dfs(edges[0][0]):
        return False
    return sum(visited) == n

